    const rawStatus=String(booking.status||'unknown').toLowerCase().replace(/[_ ]/g,'-'),label=({'no-show':'No-show'})[rawStatus]||rawStatus.charAt(0).toUpperCase()+rawStatus.slice(1).replace(/-/g,' '),tone=['confirmed','completed','cancelled','no-show'].includes(rawStatus)?rawStatus:'other';
